    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {}

    def grundy(n):
        if n in memo:
            return memo[n]

        if n == 0:
            return 0
        if n % 2 != 0:
            memo[n] = 1
            return 1

        # Option 1: Remove 1 cow
        reachable = {grundy(n - 1)}

        # Option 2: Split if possible (n is even, so n = 2 * (n//2))
        x = n // 2
        g_x = grundy(x)
        if k % 2 == 1:
            # odd k: XOR sum is g(x)
            reachable.add(g_x)
        else:
            # even k: XOR sum is 0
            reachable.add(0)

        # Compute mex
        mex = 0
        while mex in reachable:
            mex += 1
        memo[n] = mex
        return mex

    # Compute nim-sum
    nim_sum = 0
    for pile in a:
        nim_sum ^= grundy(pile)

    if nim_sum > 0:
        return Kevin\n'
    else:
        return Nicky\n'

