    adj = {}
    for idx, (i, j) in enumerate(white):
        adj[idx] = []
        for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m:
                # Find which black cell this neighbor is
                for bidx, (bi, bj) in enumerate(black):
                    if bi == ni and bj == nj:
                        adj[idx].append(bidx)
                        break

    # Maximum bipartite matching using DFS
    match = {}  # Maps black_index -> white_index

    def dfs(u, visited):
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                if v not in match or dfs(match[v], visited):
                    match[v] = u
                    return True
        return False

