def check_axis_aligned(matrix, r, c, k):
    n = len(matrix)
    m = len(matrix[0])

    # Check all border positions
    # Top row: (r, c) to (r, c+k-1)
    # Bottom row: (r+k-1, c) to (r+k-1, c+k-1)
    # Left column: (r, c) to (r+k-1, c)
    # Right column: (r, c+k-1) to (r+k-1, c+k-1)

    # Collect all border cells
    border_cells = set()
    for col in range(c, c + k):
        border_cells.add((r, col))
        border_cells.add((r + k - 1, col))
    for row in range(r + 1, r + k - 1):  # Exclude corners
        border_cells.add((row, c))
        border_cells.add((row, c + k - 1))

    # Check all border cells are '1'
    for (br, bc) in border_cells:
        if matrix[br][bc] == '0':
            return False

    # Check isolation: for each border cell, all 8 neighbors that are not border cells should be '0'
    for (br, bc) in border_cells:
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = br + dr, bc + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if (nr, nc) not in border_cells:
                        if matrix[nr][nc] == '1':
                            return False

    return True

def check_diamond(matrix, r, c, k):
    n = len(matrix)
    m = len(matrix[0])

    # Collect all border cells: cells where |row - r| + |col - c| = k
    border_cells = set()

