from collections import deque

def bfs(start, n, adj):
    """Compute shortest distances from start to all other nodes using BFS"""
    dist = [-1] * (n + 1)
    dist[start] = 0
    queue = deque([start])

    while queue:
        u = queue.popleft()
        du = dist[u]
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = du + 1
                queue.append(v)
    return dist

