from collections import deque

def solution(s):
    line1, line2 = s.strip().split('\n')
    n, k = map(int, line1.split())
    nums = map(int, line2.split())
    nums = tuple(sorted(nums))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    visited = {nums}
    queue = deque([(nums, [])])

    while queue:
        state, path = queue.popleft()

        if len(state) == 1 and state[0] == 1:
            ops = [f"{a} {b}" for a, b in path]
            return "YES\n" + "\n".join(ops)

        if len(state) > 1:
            for i in range(len(state)):
                for j in range(i + 1, len(state)):
                    a, b = state[i], state[j]
                    new_val = f(a + b)
                    remaining = list(state)
                    remaining.pop(i)
                    remaining.pop(j - 1)
                    new_state = tuple(sorted(remaining + [new_val]))

                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, path + [(a, b)]))

    return "NO"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    min_time = float('inf')

    # Try each possible starting position T
    for T in range(1, n + 1):
        # Calculate when each icicle blocks (time = sound travel + falling time)
        block_times = [abs(k + 1 - T) + a[k] for k in range(n)]

        # Prefix: minimum block time among icicles at positions (1 to i) [0-indexed]
        prefix = [float('inf')] * n
        for i in range(n):
            if i == 0:
                prefix[i] = block_times[i]
            else:
                prefix[i] = min(prefix[i - 1], block_times[i])

        # Suffix: minimum block time among icicles at positions (i to n) [0-indexed]
        suffix = [float('inf')] * n
        for i in range(n - 1, -1, -1):
            if i == n - 1:
                suffix[i] = block_times[i]
            else:
                suffix[i] = min(block_times[i], suffix[i + 1])

        # Check times t = 1 to n to find earliest entrapment
        for t in range(1, n + 1):
            # Icicles on the left: positions 1 to t-1 (0-indexed: 0 to t-2)
            # Icicles on the right: positions t+1 to n (0-indexed: t to n-1)

            if t == 1:
                left_blocked = float('inf')
            else:
                left_blocked = prefix[t - 2]

            if t == n:
                right_blocked = float('inf')
            else:
                right_blocked = suffix[t + 1]

            # Krakozyabra is entrapped if both sides have fallen icicles by time t
            if left_blocked <= t and right_blocked <= t:
                min_time = min(min_time, t)
                break

    return str(min_time) if min_time != float('inf') else '-1'


