def mod_inverse(a, p):
    # Extended Euclidean Algorithm for modular inverse
    g, x, _ = extended_gcd(a, p)
    if g != 1:
        raise ValueError("Modular inverse doesn't exist")
    return x % p

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    g, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return g, x, y

def is_quadratic_residue(d, p):
    # Use Euler's criterion: d^((p-1)/2) ≡ 1 if d is QR
    if d % p == 0:
        return True
    lsqr = pow(d, (p - 1) // 2, p)
    return lsqr == 1

