def count_factors(n):
    """Return (count2, count5) in prime factorization of n."""
    if n == 0:
        return 0, 0
    count2 = 0
    while n > 0 and n % 2 == 0:
        n //= 2
        count2 += 1
    count5 = 0
    while n > 0 and n % 5 == 0:
        n //= 5
        count5 += 1
    return count2, count5


