"""
Solution for the harmony sequence problem.
We need to find a harmony sequence b_i such that:
1. All elements are pairwise coprime (gcd(b_i, b_j) = 1 for i != j)
2. The sequence minimizes sum_{i != j} (gcd(a_i, b_i))^2
3. Each b_i <= 100 (implied from problem constraints)
"""

import math
from itertools import permutations

def gcd(x, y):
    return math.gcd(x, y)

def is_pairwise_coprime(lst):
    """Check if all pairs in the list are coprime."""
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            if gcd(lst[i], lst[j]) != 1:
                return False
    return True

def calculate_cost(a, b):
    """Calculate the total cost sum_{i=1 to n} gcd(a_i, b_i)^2."""
    total = 0
    for i in range(len(a)):
        if i < len(b):
            total += gcd(a[i], b[i]) ** 2
    return total

def is_valid_harmony(a, b):
    """Check if b is a valid harmony sequence (n elements, pairwise coprime)."""
    if len(b) != len(a):
        return False
    if not is_pairwise_coprime(b):
        return False
    if a and b:
        cost = calculate_cost(a, b)
        cost_list.append(cost)
    return True

