    raw_adj = []
    for i in range(m):
        line = lines[i + 1]
        a, b, l = map(int, line.split())
        adj[a].append((b, l))
        raw_adj.append((a, b, l))

    q = int(lines[m + 1])
    queries = []
    for i in range(q):
        line = lines[m + 2 + i]
        v, s, t = map(int, line.split())
        queries.append((v, s, t))

    # Tarjan's algorithm for SCCs
    timer = [0]
    visited = [False] * (n + 1)
    stack = []
    in_stack = [False] * (n + 1)
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)

    def dfs(u):
        visited[u] = True
        stack.append(u)
        in_stack[u] = True
        timer[0] += 1
        disc[u] = low[u] = timer[0]

        for v, w in adj[u]:
            if not visited[v]:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif in_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            scc = []
            while True:
                v = stack.pop()
                in_stack[v] = False
                scc.append(v)
                if u == v:
                    break
            sccs.append(scc)

    sccs = []
    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Compute g (GCD of all cycle lengths) for each SCC
    vertex_g = [0] * (n + 1)

    for scc in sccs:
        g = 0
        if len(scc) == 1:
            g = 0  # Single vertex means no cycles
        else:
            # Build subgraph for this SCC
            scc_adj = defaultdict(list)
            for a, b, l in raw_adj:
                if a in scc and b in scc:
                    scc_adj[a].append((b, l))

            # Run Dijkstra from an arbitrary vertex in SCC
            r = scc[0]
            dist = {node: float('inf') for node in scc}
            dist[r] = 0
            pq = [(0, r)]

            while pq:
                d, u = heapq.heappop(pq)
                if d > dist[u]:
                    continue
                for v, w in scc_adj[u]:
                    nd = d + w
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(pq, (nd, v))

            # Compute GCD of w' = w + dist[u] - dist[v] for all edges in SCC
            for a, b, l in raw_adj:
                if a in scc and b in scc:
                    if dist[a] < float('inf') and dist[b] < float('inf'):
                        w_prime = l + dist[a] - dist[b]
                        g = math.gcd(g, w_prime)

        for v in scc:
            vertex_g[v] = g

    output = []
    for v, s, t in queries:
        g = vertex_g[v]

        # If s == 0, already at odometer reading 0, no driving needed
        if s == 0:
            output.append("YES")
        elif g == 0:
            # Single vertex SCC, no cycles, can't drive anywhere
            output.append("NO")
        else:
            # Check if s % gcd(g, t) == 0
            gtt = math.gcd(g, t)
            if s % gtt == 0:
                output.append("YES")
            else:
                output.append("NO")

    return '\n'.join(output)

