        priorities.append(row)

    def compare_p(g1, g2):
        """Compare two grids by priority - returns -1 if g1 < g2, 1 if g1 > g2, 0 if equal"""
        cells_by_priority = {}
        for r in range(n):
            for c in range(m):
                cells_by_priority[priorities[r][c]] = (r, c)

        for p in sorted(cells_by_priority.keys()):
            r, c = cells_by_priority[p]
            if g1[r][c] != g2[r][c]:
                return -1 if g1[r][c] == '(' else 1
        return 0

    def is_valid(grid):
        """Check if all monotonic paths from (0,0) to (n-1,m-1) form valid bracket sequences"""
        def dfs(i, j, balance):
            # At destination
            if i == n - 1 and j == m - 1:
                return balance == 0

            char = ('(' if grid[i][j] == '(' else ')')
            balance += 1 if char == '(' else -1

            # Balance must never be negative
            if balance < 0:
                return False

            # Try moving down or right
            result_down = False
            result_right = False

            if i + 1 < n:
                result_down = dfs(i + 1, j, balance)
            if not result_down and j + 1 < m:
                result_right = dfs(i, j + 1, balance)

            return result_down or result_right

        # First character must be '('
        if grid[0][0] != '(':
            return False

        return dfs(0, 0, 0)

    def get_grid(bits):
        """Convert bits tuple to grid"""
        grid = []
        idx = 0
        for r in range(n):
            row = []
            for c in range(m):
                if idx < len(bits):
                    row.append(bits[idx])
                    idx += 1
                else:
                    row.append('')
            grid.append(row)
        return grid

    # Generate all valid grids
    valid_grids = []
    for bits in product(['(', ')'], repeat=n * m):
        grid = get_grid(bits)
        if is_valid(grid):
            valid_grids.append(grid)

    # Sort by priority comparison
    valid_grids.sort(key=lambda g: [0] * (n * m))

    # Use a stable sort with comparison
    for i in range(len(valid_grids)):
        valid_grids[i] = valid_grids[i]

    # Sort properly using the comparison function
    valid_grids.sort(key=lambda g: tuple(
        g[priorities[r][c] // (n * m)] for r in range(n) for c in range(m)
    ))

    if len(valid_grids) >= k:
        result = valid_grids[k - 1]
        for row in result:
            print(''.join(row))
    else:
        return ""

