        return str(len(n_str) * (len(n_str) // 2 + 3))

    # BFS for reasonable bounds
    from collections import deque

    visited = {n}
    queue = deque([(n, 0)])

    # Depth limit to prevent TLE
    depth_limit = 2000000 if n > 10**15 else n + 1000

    while queue:
        num, steps = queue.popleft()

        if num == 0:
            return str(steps)

        if steps > depth_limit:
            break

