    return "0"

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    attempts = []
    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        s = parts[0]
        c = int(parts[1])
        attempts.append((s, c))

    if not attempts:
        return str(2 ** n)

    left_len = n // 2
    right_len = n - left_len

    target = tuple(c for _, c in attempts)

    # Precompute match counts for left half (positions 0 to left_len-1)
    left = {}
    for mask in range(1 << left_len):
        matches = []
        for s, c in attempts:
            matches.append(sum(1 for j in range(left_len) if (mask >> j) & 1 == int(s[j])))
        left[tuple(matches)] = left.get(tuple(matches), 0) + 1

    # Precompute match counts for right half (positions left_len to n-1)
    right = {}
    for mask in range(1 << right_len):
        matches = []
        for s, c in attempts:
            matches.append(sum(1 for j in range(right_len) if (mask >> j) & 1 == int(s[left_len + j])))
        right[tuple(matches)] = right.get(tuple(matches), 0) + 1

    # Combine left and right halves - sum must equal target for each position
    total = 0
    for l_sum in left:
        needed = tuple(target[j] - l_sum[j] for j in range(len(target)))
        if needed in right:
            total += left[l_sum] * right[needed]

    return str(total)


